insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values('support-attachments','support-attachments',false,15728640,array['image/jpeg','image/png','image/webp','application/pdf','text/plain'])
on conflict(id) do update set public=false,file_size_limit=15728640,allowed_mime_types=excluded.allowed_mime_types;
drop policy if exists support_attachment_upload on storage.objects;
create policy support_attachment_upload on storage.objects for insert to authenticated with check(bucket_id='support-attachments' and (storage.foldername(name))[1] ~* '^[0-9a-f-]{36}$' and (storage.foldername(name))[2]=(select auth.uid())::text and exists(select 1 from public.support_tickets t where t.id::text=(storage.foldername(name))[1] and (t.user_id=(select auth.uid()) or (t.assigned_agent_id=(select auth.uid()) and exists(select 1 from public.support_agents a where a.user_id=(select auth.uid()) and a.is_active)))));
drop policy if exists support_attachment_read on storage.objects;
create policy support_attachment_read on storage.objects for select to authenticated using(bucket_id='support-attachments' and (storage.foldername(name))[1] ~* '^[0-9a-f-]{36}$' and exists(select 1 from public.support_tickets t where t.id::text=(storage.foldername(name))[1] and (t.user_id=(select auth.uid()) or (t.assigned_agent_id=(select auth.uid()) and exists(select 1 from public.support_agents a where a.user_id=(select auth.uid()) and a.is_active)))));
alter table public.support_messages drop constraint if exists support_messages_attachment_limit;
alter table public.support_messages add constraint support_messages_attachment_limit check(cardinality(attachment_paths)<=5);
drop policy if exists support_messages_create_owner_or_agent on public.support_messages;
create policy support_messages_create_owner_or_agent on public.support_messages for insert to authenticated with check(sender_id=(select auth.uid()) and is_internal=false and cardinality(attachment_paths)<=5 and not exists(select 1 from unnest(attachment_paths) p where split_part(p,'/',1)<>ticket_id::text or split_part(p,'/',2)<>sender_id::text or p !~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/[A-Za-z0-9._-]{1,180}$') and exists(select 1 from public.support_tickets t where t.id=ticket_id and t.user_id=(select auth.uid()) and t.status<>'closed'));
drop policy if exists support_messages_create_agent on public.support_messages;
create policy support_messages_create_agent on public.support_messages for insert to authenticated with check(sender_id=(select auth.uid()) and exists(select 1 from public.support_agents a where a.user_id=(select auth.uid()) and a.is_active) and exists(select 1 from public.support_tickets t where t.id=ticket_id and t.assigned_agent_id=(select auth.uid())) and cardinality(attachment_paths)<=5 and not exists(select 1 from unnest(attachment_paths) p where split_part(p,'/',1)<>ticket_id::text or split_part(p,'/',2)<>sender_id::text or p !~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/[A-Za-z0-9._-]{1,180}$'));
grant insert(ticket_id,sender_id,body,is_internal,attachment_paths) on public.support_messages to authenticated;
